def log(message: str) -> bool:
    """log writes one line to the server log under the mod's name."""
    return _call("Log", "LogRequest", {"message": message}) is not None


def server_command(command: str) -> bool:
    """server_command runs one line at the server console, as if typed there. A
    line that sets a variable may set a development-only or cheat-protected
    one. A line that reaches the engine's controls for files, logging, the
    network or the process, or stores a command to run later, is refused with
    the name of the command.
    """
    return _call("ServerCommand", "ServerCommandRequest", {"command": command}) is not None


def precache(options: PrecacheOptions) -> bool:
    """precache loads heroes and resources with the next world. Call it during
    start, before the first world loads; a call after that, such as from a
    reload, prepares only the world after the next map change. Name every
    hero whose abilities ReplaceAbility gives, with their particles.
    """
    return _call("Precache", "PrecacheOptions", options) is not None


def read_file(path: str) -> str | None:
    """read_file reads one of the mod's files: the host's copy, which the mod
    wrote or the server's operator placed, else the one the mod ships under
    data/. A file in neither reads as unset. Names that leave the mod's
    directories are refused.
    """
    response = _call("ReadFile", "ReadFileRequest", {"path": path}, "ReadFileResponse")
    if response is None:
        return None
    return response["text"]


def write_file(path: str, text: str) -> bool:
    """write_file replaces one of the mod's files in the host's copy, which
    outlives a restart and an update of the mod; the files the mod ships stay
    as they are. The write is whole or not at all, and the host refuses one
    past its quota of 4 MiB per mod. A host that keeps no files refuses every
    write.
    """
    return _call("WriteFile", "WriteFileRequest", {"path": path, "text": text}) is not None


def hold_reload(held: bool) -> bool:
    """hold_reload keeps the running build through a reload while held is true,
    such as while a player is partway through something a new build would
    lose. A reload that arrives meanwhile waits, and the newest one applies
    on the first frame after the mod releases the hold. A new build starts
    without a hold.
    """
    return _call("HoldReload", "HoldReloadRequest", {"held": held}) is not None


def handoff(text: str) -> bool:
    """handoff replaces the handoff state for the game: what the running build
    hands the next build when the mod reloads, such as which round it plays.
    It lasts only through a reload of the mod in the same game, such as an
    update, whose new build reads it back with HandedOff. The host holds it
    in memory and never writes it to disk, so it ends when the mod stops or
    the server restarts. The host refuses state past 64 KiB.
    """
    return _call("Handoff", "HandoffRequest", {"text": text}) is not None


def handed_off() -> str | None:
    """handed_off returns the game's handoff state, or empty."""
    response = _call("HandedOff", "Empty", {}, "HandedOffResponse")
    if response is None:
        return None
    return response["text"]


def hero_build(hero: str) -> list[BuildCategory]:
    """hero_build reads a hero's recommended build from the host's game data:
    its categories of items in buying order. Items the game does not define
    are left out, so every item returned is one GiveItem accepts. A hero
    without a build answers with no categories. The call needs a loaded
    world.
    """
    response = _call("HeroBuild", "HeroBuildRequest", {"hero": hero}, "HeroBuildResponse")
    if response is None:
        return []
    return response["categories"]


def silence_voice(concepts: list[str] | None = None) -> bool:
    """silence_voice keeps every hero from speaking the named voice concepts,
    until called again. A hero still hears the game's other sounds. Stopping
    the mod lets them speak; a name the game does not know fails the call
    and the known ones still apply.
    """
    return _call("SilenceVoice", "SilenceVoiceRequest", {"concepts": concepts}) is not None


def read_field(entity: int, class_name: str, field: str, type: FieldType) -> FieldValue | None:
    """read_field reads one schema field of a live entity, such as the int32
    m_iHealth of CBaseEntity. The host finds the field by name, so it
    survives game updates that move it, and refuses an entity that is not of
    the named class or a subclass. The match's state, such as the gold of each
    team or the winning team, is a field of CCitadelGameRules, which the
    citadel_gamerules entity reads. The parts of an entity's model that its
    body component holds read through the entity too: CGameSceneNode, and for
    a model entity CSkeletonInstance and CModelState, such as the uint64
    m_MeshGroupMask of CModelState that chooses which mesh groups draw.
    """
    response = _call("ReadField", "ReadFieldRequest", {"entity": entity, "class_name": class_name, "field": field, "type": type}, "FieldResponse")
    if response is None:
        return None
    return response["value"]


def read_modifier_field(entity: int, modifier: str, class_name: str, field: str, type: FieldType) -> FieldValue | None:
    """read_modifier_field reads one schema field of a modifier the entity holds,
    such as the int32 m_nCameraLevel of CCitadel_Modifier_OrbitCamera on a
    pawn holding modifier_citadel_orbit_camera. The answer holds no value
    while the entity lacks the modifier. The host cannot check the modifier's
    class, so a wrong class reads the wrong bytes, though never past readable
    memory.
    """
    response = _call("ReadModifierField", "ReadModifierFieldRequest", {"entity": entity, "modifier": modifier, "class_name": class_name, "field": field, "type": type}, "FieldResponse")
    if response is None:
        return None
    return response["value"]


def write_field(entity: int, class_name: str, field: str, type: FieldType, value: FieldValue) -> bool:
    """write_field writes one schema field of a live entity and sends the change
    to the players. The value takes the form ReadField returns for the type.
    Text goes only to a symbol field (string_t, such as the m_DialogXMLName of
    a point_clientui_world_panel), with {addon} replaced by the mod's content
    addon as in an entity's key values; a CUtlString field owns its text and
    cannot be written. A write to the match's state sends all of it, so
    players already in the match see the change, and a write to a model part,
    as ReadField names them, sends the entity. A client builds a client UI
    entity's panel only when it creates the entity, so a write to
    m_DialogXMLName sends every client a full update on the next frame, which
    creates every entity again; the players' game stalls briefly, so write a
    layout when it changes, not every frame. It refuses the fields that
    name a console line or a script, such as m_iszPrivateVScripts, here and
    among the fields CreateEntity writes before spawn.
    """
    return _call("WriteField", "WriteFieldRequest", {"entity": entity, "class_name": class_name, "field": field, "type": type, "value": value}) is not None


def read_field_list(entity: int, class_name: str, field: str, type: FieldType) -> list[FieldValue]:
    """read_field_list reads a field that holds a list, such as the m_vecBannedHeroes
    of CCitadelGameRules. The type is the type of one element: a number, a
    handle, a boolean or a vector. A list of structures cannot be read.
    """
    response = _call("ReadFieldList", "ReadFieldRequest", {"entity": entity, "class_name": class_name, "field": field, "type": type}, "FieldListResponse")
    if response is None:
        return []
    return response["values"]


def write_field_list(entity: int, class_name: str, field: str, type: FieldType, values: list[FieldValue] | None = None) -> bool:
    """write_field_list replaces the elements of a list field and sends the change
    to the players, growing the list when it holds fewer elements than the
    new ones.
    """
    return _call("WriteFieldList", "WriteFieldListRequest", {"entity": entity, "class_name": class_name, "field": field, "type": type, "values": values}) is not None


def entity_class(entity: int) -> EntityClassName | None:
    """entity_class returns a live entity's schema class, such as
    CCitadelPlayerPawn, whose fields ReadField reads, and its designer name.
    """
    response = _call("EntityClass", "EntityRequest", {"entity": entity}, "EntityClassResponse")
    if response is None:
        return None
    return response["name"]


def entity_name(entity: int) -> str | None:
    """entity_name returns a live entity's name, the targetname a map or a spawn
    key value gave it, or an empty name for an unnamed entity.
    """
    response = _call("EntityName", "EntityRequest", {"entity": entity}, "EntityNameResponse")
    if response is None:
        return None
    return response["name"]


def entity_position(entity: int) -> EntityPlacement | None:
    """entity_position returns where a live entity stands, its absolute origin
    and angles, as MoveEntity places it, and its velocity. Any entity with a
    place in the world has one, such as one of the map's boxes.
    """
    response = _call("EntityPosition", "EntityRequest", {"entity": entity}, "EntityPositionResponse")
    if response is None:
        return None
    return response["placement"]


def modifier_state(entity: int, state: str) -> bool:
    """modifier_state reports whether an entity has a modifier state, such as
    MODIFIER_STATE_PARRY_ACTIVE.
    """
    response = _call("ModifierState", "ModifierStateRequest", {"entity": entity, "state": state}, "ActiveResponse")
    if response is None:
        return False
    return response["active"]


def hold_modifier_state(entity: int, state: str, active: bool | None = None) -> bool:
    """hold_modifier_state holds a modifier state, such as
    MODIFIER_STATE_FRIENDLY_FIRE_ENABLED, on an entity while the mod runs, or
    releases the hold. The hold ends with the entity.
    """
    return _call("HoldModifierState", "HoldModifierStateRequest", {"entity": entity, "state": state, "active": active}) is not None


def set_free_for_all(enabled: bool) -> bool:
    """set_free_for_all turns free-for-all on or off for the running mod, over the
    Manifest's free_for_all default. While on, the host seats each new player
    on the smaller team with no team screen, holds friendly fire on every
    hero, makes teammates enemies to abilities, projectiles and target
    checks, and ignores changeteam commands. The stock hero picker does not
    open for a seated player, so the mod gives each seated player whose pawn
    has hero 0 a hero with SelectHero. Turning it off releases the friendly
    fire holds and restores stock team relations; players keep their teams.
    Clients still draw teammates as allies.
    """
    return _call("SetFreeForAll", "SetFreeForAllRequest", {"enabled": enabled}) is not None


def set_team_seating(enabled: bool) -> bool:
    """set_team_seating turns team seating on or off for the running mod. While
    on, the host seats each player who joins with no team on the smaller
    team with no team screen; friendly fire and changeteam stay as the game
    has them. The stock hero picker does not open for a seated player, so
    the mod gives each seated player whose pawn has hero 0 a hero with
    SelectHero. Free-for-all seats players this
    way whatever this says. Turning it off leaves players on their teams.
    """
    return _call("SetTeamSeating", "SetTeamSeatingRequest", {"enabled": enabled}) is not None


def create_model(options: ModelOptions) -> WorldObject | None:
    """create_model places a model in the world, solid when the options ask.
    The world removes it when the world ends; stopping the mod removes it
    too.
    """
    response = _call("CreateModel", "ModelOptions", options, "ObjectResponse")
    if response is None:
        return None
    return response["object"]


def create_text(options: TextOptions) -> WorldObject | None:
    """create_text places text that floats in the world."""
    response = _call("CreateText", "TextOptions", options, "ObjectResponse")
    if response is None:
        return None
    return response["object"]


def create_particle(options: ParticleOptions) -> WorldObject | None:
    """create_particle starts a particle effect. Removing the object stops it
    and lets its end cap play out, unless the mod already stopped it, such as
    with the DestroyImmediately input; moving it moves the effect.
    """
    response = _call("CreateParticle", "ParticleOptions", options, "ObjectResponse")
    if response is None:
        return None
    return response["object"]


def create_fog(options: FogOptions) -> WorldObject | None:
    """create_fog fills a box with tinted fog whose density fades across the
    box's boundary. Removing the object clears it; moving it moves the box.
    """
    response = _call("CreateFog", "FogOptions", options, "ObjectResponse")
    if response is None:
        return None
    return response["object"]


def add_bot(options: BotOptions) -> Player | None:
    """add_bot adds a bot player and returns it. The bot leaves when the world
    ends or the mod stops.
    """
    response = _call("AddBot", "BotOptions", options, "BotResponse")
    if response is None:
        return None
    return response["player"]


def block_input(buttons: int) -> bool:
    """block_input withholds buttons from every player's hero until called
    again. Stopping the mod releases them.
    """
    return _call("BlockInput", "InputRequest", {"buttons": buttons}) is not None


def watch_input(buttons: int) -> bool:
    """watch_input replaces the buttons whose presses and releases arrive as
    Input events. Watching does not withhold a press; block it with
    BlockInput.
    """
    return _call("WatchInput", "InputRequest", {"buttons": buttons}) is not None


def remap_input(from_: int, to: int, repeat: bool | None = None) -> bool:
    """remap_input makes the from buttons act as the to buttons for every
    player's hero until called again; from reads as up. With repeat, a held
    from button uses the to ability again as soon as it is ready. A zero from
    stops remapping, and stopping the mod does too. BlockInput applies after
    the remap.
    """
    return _call("RemapInput", "RemapInputRequest", {"from_": from_, "to": to, "repeat": repeat}) is not None


def call_service(service: str, method: str, payload: bytes) -> bytes | None:
    """call_service calls method of a service the host provides outside Modlock,
    such as a game mode's match, and returns the service's answer. The
    service defines the payload's encoding.
    """
    response = _call("CallService", "ServiceCall", {"service": service, "method": method, "payload": payload}, "ServiceReply")
    if response is None:
        return None
    return response["payload"]


def create_entity(options: EntityOptions) -> int | None:
    """create_entity creates an entity the server knows by its designer name,
    such as npc_trooper_boss or prop_dynamic, with spawn key values and fields
    written before it spawns. The world removes it when the world ends;
    stopping the mod removes it too. It refuses an ability, item or weapon,
    which only a hero holds: GiveItem and ReplaceAbility give one. It refuses
    a class that runs console lines or loads scripts or entities past a mod's
    checks, such as point_servercommand, and key values that name a console
    line or a script, such as vscripts.
    """
    response = _call("CreateEntity", "EntityOptions", options, "EntityResponse")
    if response is None:
        return None
    return response["entity"]


def fire_input(entity: int, input: str, value: EntityValue | None = None, activator: int | None = None) -> bool:
    """fire_input sends an input to a live entity, as a map's output would, such
    as Skin with the integer 1. The value must have the type the input reads.
    It reports false once the entity is gone. It refuses AddOutput and the
    script inputs on every entity, and any input to an entity of a class
    CreateEntity refuses.
    """
    response = _call("FireInput", "FireInputRequest", {"entity": entity, "input": input, "value": value, "activator": activator}, "AliveResponse")
    if response is None:
        return False
    return response["alive"]


def remove_entity(entity: int) -> bool:
    """remove_entity takes an entity the mod created out of the world without
    rewards. It reports false when the entity was already gone.
    """
    response = _call("RemoveEntity", "EntityRequest", {"entity": entity}, "AliveResponse")
    if response is None:
        return False
    return response["alive"]


def show_entity_only_to(entity: int, players: list[int] | None = None) -> bool:
    """show_entity_only_to sends an entity the mod created only to the players with
    the listed server slots; every other client drops it, or never receives
    it when the call follows its creation in the same frame. With no players
    no client receives it. The list replaces any earlier one. A player who
    leaves is taken off every list, so whoever joins in their slot does not
    receive the entity. The rule holds for an entity created with
    TransmitAlways too, but not for entities parented to it, which need their
    own call. Removing the entity, the world ending or the mod stopping drops
    the rule.
    """
    return _call("ShowEntityOnlyTo", "ShowEntityOnlyToRequest", {"entity": entity, "players": players}) is not None


def show_entity_to_all(entity: int) -> bool:
    """show_entity_to_all sends an entity the mod created to every player the game
    would send it to again, undoing ShowEntityOnlyTo.
    """
    return _call("ShowEntityToAll", "EntityRequest", {"entity": entity}) is not None


def spawn_npc(options: NpcOptions) -> Npc | None:
    """spawn_npc adds a unit that is not a player, such as a trooper, as
    CreateEntity does, then sets its health and lane. It thinks from the next
    frame. The world removes it when the world ends; stopping
    the mod removes it too.
    """
    response = _call("SpawnNpc", "NpcOptions", options, "NpcResponse")
    if response is None:
        return None
    return response["npc"]


def create_pickup(kind: PickupKind, position: Vector) -> Pickup | None:
    """create_pickup places an urn, which a hero carries once collected, or a
    movement buff. Stopping the mod removes it.
    """
    response = _call("CreatePickup", "CreatePickupRequest", {"kind": kind, "position": position}, "PickupResponse")
    if response is None:
        return None
    return response["pickup"]


def find_entities(class_name: str) -> list[int]:
    """find_entities returns the handle of every live entity of a class, such as
    zip_line_node.
    """
    response = _call("FindEntities", "FindEntitiesRequest", {"class_name": class_name}, "EntitiesResponse")
    if response is None:
        return []
    return response["entities"]


def find_entities_by_name(name: str) -> list[int]:
    """find_entities_by_name returns the handle of every live entity with a name,
    the targetname a map or the targetname key value of CreateEntity gave it.
    """
    response = _call("FindEntitiesByName", "FindEntitiesByNameRequest", {"name": name}, "EntitiesResponse")
    if response is None:
        return []
    return response["entities"]


def remove_entities(class_name: str) -> int | None:
    """remove_entities removes every entity of a class, such as npc_trooper,
    without rewards, and returns how many it removed.
    """
    response = _call("RemoveEntities", "RemoveEntitiesRequest", {"class_name": class_name}, "CountResponse")
    if response is None:
        return None
    return response["count"]


def clear_map() -> bool:
    """clear_map removes the map's own units and objectives, such as troopers,
    guardians and walkers, so a mode can use the map as an arena.
    """
    return _call("ClearMap", "Empty", {}) is not None


def damage(options: HitOptions) -> bool:
    """damage deals a hit as the game would. The mod's Damage events do not
    include its own hits.
    """
    return _call("Damage", "HitOptions", options) is not None


def kill_entity(options: KillOptions) -> bool:
    """kill_entity forces a hero or unit to die, optionally crediting an attacker.
    Already dead victims succeed without another death or reward.
    """
    return _call("KillEntity", "KillOptions", options) is not None


def trace(options: TraceOptions) -> TraceHit | None:
    """trace returns where a line first hits something, or nothing when it hits
    nothing or the world's collision is not ready.
    """
    response = _call("Trace", "TraceOptions", options, "TraceResponse")
    if response is None:
        return None
    return response["hit"]


def restore_npcs(npcs: list[NpcTarget] | None = None) -> bool:
    """restore_npcs replaces the map's lane units and objectives with targets
    over the next frames. Units of these classes not in the list are
    removed, structures that match are kept, and moving units are spawned
    again in place. An NpcsRestored event reports when every target stands
    as its own unit, or why not. A new call replaces the running one.
    """
    return _call("RestoreNpcs", "RestoreNpcsRequest", {"npcs": npcs}) is not None


def pause(paused: bool) -> bool:
    """pause stops or resumes the game clock, as the pause command would.
    Stopping the mod resumes it.
    """
    return _call("Pause", "PauseRequest", {"paused": paused}) is not None


def match_clock() -> float | None:
    """match_clock returns the match time in seconds that the scoreboard shows."""
    response = _call("MatchClock", "Empty", {}, "MatchClockResponse")
    if response is None:
        return None
    return response["seconds"]


def hold_match_clock(seconds: float | None = None) -> bool:
    """hold_match_clock keeps the match time at seconds every frame until called
    again; omitted seconds let it run.
    """
    return _call("HoldMatchClock", "HoldMatchClockRequest", {"seconds": seconds}) is not None


def rift() -> RiftState | None:
    """rift reads the Rift objective's state."""
    response = _call("Rift", "Empty", {}, "RiftResponse")
    if response is None:
        return None
    return response["state"]


def start_rift(position: Vector) -> bool:
    """start_rift opens the Rift objective at position now."""
    return _call("StartRift", "StartRiftRequest", {"position": position}) is not None


def move_entity(entity: int, position: Vector | None = None, facing: Angles | None = None, velocity: Vector | None = None) -> bool:
    """move_entity places any entity, such as a projectile, and replaces its
    facing and motion when given. Without a position it leaves the entity
    where it is, so a velocity alone steers a body the physics simulates, such
    as a prop_physics, which carries the motion on against the world.
    """
    return _call("MoveEntity", "MoveEntityRequest", {"entity": entity, "position": position, "facing": facing, "velocity": velocity}) is not None


def push_entity(entity: int, velocity: Vector, spin: Vector | None = None) -> bool:
    """push_entity adds a velocity and an angular velocity to any entity. On a
    body the physics simulates, such as a prop_physics, it acts like an
    impulse that the simulation carries on.
    """
    return _call("PushEntity", "PushEntityRequest", {"entity": entity, "velocity": velocity, "spin": spin}) is not None


def emit_sound(entity: int, sound: str, options: SoundOptions | None = None) -> int | None:
    """emit_sound plays one game sound on any entity, such as a projectile, and
    returns its ID. Volume and pitch scale the sound, and listeners limit who
    hears it.
    """
    response = _call("EmitSound", "EmitSoundRequest", {"entity": entity, "sound": sound, "options": options}, "SoundResponse")
    if response is None:
        return None
    return response["id"]


def adjust_sound(id: int, volume: float | None = None, pitch: float | None = None) -> bool:
    """adjust_sound changes the volume or pitch of a sound Sound or EmitSound
    started, while it plays.
    """
    return _call("AdjustSound", "AdjustSoundRequest", {"id": id, "volume": volume, "pitch": pitch}) is not None


def stop_sound(id: int) -> bool:
    """stop_sound stops a sound Sound or EmitSound started. A sound that already
    ended is not an error.
    """
    return _call("StopSound", "StopSoundRequest", {"id": id}) is not None


def watch_projectiles(options: ProjectileOptions) -> bool:
    """watch_projectiles reports the projectiles with these designer names, such
    as rocket_launcher_rocket_projectile, in Launch and Impact events. A new
    call replaces the list; an empty list stops watching.
    """
    return _call("WatchProjectiles", "ProjectileOptions", options) is not None


def hold_entity_modifier(entity: int, modifier: str, active: bool | None = None) -> bool:
    """hold_entity_modifier keeps a modifier, named as GiveModifier names it, on a
    live entity with no expiry, giving it back whenever the game removes it
    while the entity lives. The hold ends with the entity or when active is
    false.
    """
    return _call("HoldEntityModifier", "HoldEntityModifierRequest", {"entity": entity, "modifier": modifier, "active": active}) is not None


def give_entity_modifier(entity: int, modifier: str, seconds: float) -> bool:
    """give_entity_modifier gives a live entity, such as Npc.entity or Pawn.entity,
    a modifier for seconds. An ability's modifier, named
    "<ability>/<modifier>", resolves its parent ability subclass even when the
    entity owns no abilities.
    """
    return _call("GiveEntityModifier", "GiveEntityModifierRequest", {"entity": entity, "modifier": modifier, "seconds": seconds}) is not None


# _EVENTS holds each Mod method's request, response and handler.
_EVENTS: dict[str, tuple[str, str, str]] = {
    "Start": ("StartEvent", "StartResult", "start"),
    "Frame": ("FrameEvent", "Empty", "frame"),
    "Command": ("CommandEvent", "CommandResult", "command"),
    "Chat": ("ChatEvent", "Empty", "chat"),
    "World": ("WorldEvent", "Empty", "world"),
    "UiPress": ("UiPressEvent", "Empty", "ui_press"),
    "UiInput": ("UiInputEvent", "Empty", "ui_input"),
    "Serve": ("ServiceCall", "ServiceReply", "serve"),
    "Damage": ("DamageEvent", "DamageResult", "damage"),
    "Damaged": ("DamagedEvent", "Empty", "damaged"),
    "Input": ("InputEvent", "Empty", "input"),
    "Restored": ("RestoredEvent", "Empty", "restored"),
    "NpcsRestored": ("NpcsRestoredEvent", "Empty", "npcs_restored"),
    "Launch": ("LaunchEvent", "Empty", "launch"),
    "Impact": ("ImpactEvent", "Empty", "impact"),
    "Landed": ("LandedEvent", "Empty", "landed"),
    "SettingChanged": ("SettingChangedEvent", "Empty", "setting_changed"),
    "PlayerJoined": ("PlayerJoinedEvent", "Empty", "player_joined"),
    "PlayerLeft": ("PlayerLeftEvent", "Empty", "player_left"),
    "PlayersChanged": ("PlayersChangedEvent", "Empty", "players_changed"),
}


def _serve_mod(handlers: Mapping[str, Callable[[Any], Any]], data: bytes) -> bytes:
    """_serve_mod runs the encoded Call in data on handlers and returns the
    encoded Reply. A handler that raises answers with its error and
    traceback."""
    request = wire.decode(_SCHEMA, "Call", data)
    event = _EVENTS.get(request["method"])
    if event is None:
        return wire.encode(_SCHEMA, "Reply", {"error": "the mod has no method " + request["method"]})
    try:
        answer = handlers[event[2]](wire.decode(_SCHEMA, event[0], request["request"]))
        response = wire.encode(_SCHEMA, event[1], answer)
    except Exception:
        return wire.encode(_SCHEMA, "Reply", {"error": traceback.format_exc().rstrip()})
    return wire.encode(_SCHEMA, "Reply", {"response": response})


# The modlock library writes Modlock mods in Python. A mod registers its
# handlers when its main module runs; modlock-host runs the mod in a sandbox
# inside the game server and calls the handlers on the server's frame
# thread, one at a time.
#
#   import modlock
#
#   @modlock.command("hello")
#   def hello(player: modlock.Player, args: str) -> None:
#       player.chat("Hello from Python!")
#
# Build it with modlock build.
#
# The calls into the game and their types above are generated from the
# schema. A call that fails logs why in the server log and returns False or
# None, so a mod can retry on a later frame instead of stopping. print writes
# to the server log.

import math
import random

from .heroes import HEROES as HEROES
from .heroes import Hero as Hero
from .heroes import find_hero as find_hero
from .heroes import hero_named as hero_named


class Buttons(enum.IntFlag):
    """Buttons names input bits for block_input, watch_input and
    Player.press."""

    # ATTACK is the primary fire button.
    ATTACK = 1
    # JUMP is the jump key, Space by default (IN_MANTLE). Blocking it stops
    # the native jump and mantle; the jumping client still predicts the jump
    # and is corrected.
    JUMP = 1 << 48
    # CROUCH is the crouch key, Ctrl by default.
    CROUCH = 1 << 2
    # DASH is the dash key, Shift by default.
    DASH = 1 << 16
    # USE is the interact key.
    USE = 1 << 5
    # ALT_FIRE is the zoom and alternate fire button, right mouse by default.
    ALT_FIRE = 1 << 11
    # RELOAD is the reload key.
    RELOAD = 1 << 13
    # MELEE is the light melee key, Q by default.
    MELEE = 1 << 32
    # ABILITY1 to ABILITY3 are the hero's first three ability keys.
    ABILITY1 = 1 << 33
    ABILITY2 = 1 << 34
    ABILITY3 = 1 << 35
    # ULTIMATE is the hero's ultimate ability key, the fourth.
    ULTIMATE = 1 << 36
    # PARRY is the melee parry button.
    PARRY = 1 << 42


class Layers(enum.IntFlag):
    """Layers names collision layers for trace, as bits."""

    # SOLID is the world and solid objects.
    SOLID = 1
    # HITBOX is the hit boxes of heroes and units.
    HITBOX = 1 << 1
    # TRIGGER is invisible volumes that react to touch.
    TRIGGER = 1 << 2
    # PLAYER_CLIP is walls that only stop heroes.
    PLAYER_CLIP = 1 << 4
    # PLAYER is player-controlled heroes.
    PLAYER = 1 << 18
    # NPC is units that are not players.
    NPC = 1 << 19
    # STATIC_LEVEL is the map's built geometry, foliage included.
    STATIC_LEVEL = 1 << 30
    # HERO, TROOPER and BUILDING are those units' bodies.
    HERO = 1 << 37
    TROOPER = 1 << 38
    BUILDING = 1 << 40


# Service answers the host's calls to one service the mod serves: the
# method's name and payload in, the answer out. An exception becomes the
# call's error.
type Service = Callable[[str, bytes], bytes]

# _commands maps each registered command name to its handler.
_commands: dict[str, Callable[[Player, str], object]] = {}

# _services maps each service the mod serves to its handler.
_services: dict[str, Service] = {}

# Each list runs in registration order.
_starts: list[Callable[[list[str]], object]] = []
_frames: list[Callable[[FrameEvent], object]] = []
_chats: list[Callable[[ChatEvent], object]] = []
_joins: list[Callable[[PlayerJoinedEvent], object]] = []
_leaves: list[Callable[[PlayerLeftEvent], object]] = []
_worlds: list[Callable[[str], object]] = []
_inputs: list[Callable[[Player, Buttons, Buttons], object]] = []
_restoreds: list[Callable[[Player, str | None], object]] = []
_npcs_restoreds: list[Callable[[str | None], object]] = []
_damages: list[Callable[[DamageEvent], DamageResult | None]] = []
_damageds: list[Callable[[DamagedEvent], object]] = []
_launches: list[Callable[[LaunchEvent], object]] = []
_impacts: list[Callable[[ImpactEvent], object]] = []
_landeds: list[Callable[[LandedEvent], object]] = []
_setting_changes: list[Callable[[Player, str, str], object]] = []

def seat_players(
    *,
    hero: str | int = "any",
    team: int | Callable[[Connection], int] | None = None,
    respawn: float | None = None,
) -> Cast[Connection]:
    """seat_players gives every player who joins a hero on a team, skipping
    the game's team and hero screens, and keeps them seated for the rest of
    the game: it brings a fallen hero back after respawn seconds and seats a
    player again after a hero change.

        modlock.seat_players(hero="any", respawn=3)

    hero is each player's hero: its name as players know it or as the game
    does, such as "Calico" or "hero_nano", its id, or "any" for the hero they
    have or else a random one. team is the team, 2 or 3, every player joins,
    or a function that picks the team for one player as they join; without
    one each player joins the side with fewer heroes. Without respawn a fallen hero is left to the game.

    It returns the Cast that does the seating, whose members are the players'
    connections, and runs it each frame itself."""
    # Decide each player's seat once, as they join, and keep it by slot.
    wants: dict[int, Want] = {}

    def join(connection: Connection) -> Connection:
        side = team(connection) if callable(team) else team
        wants[connection.player.slot] = Want(hero=hero, team=side, respawn=respawn)
        return connection

    def leave(member: Connection, connection: Connection) -> None:
        wants.pop(connection.player.slot, None)

    cast = Cast(join, leave=leave, want=lambda member: wants[member.player.slot])

    # Run the cast with the mod's frames.
    _frames.append(lambda event: cast.frame(event.time_seconds))
    return cast


_spawns: list[Callable[[Player, Pawn], object]] = []

# _spawned maps each slot whose hero is in play to that hero's entity, as the
# spawn handlers last heard of it.
_spawned: dict[int, int] = {}

# _roster is the player list the host last reported, or None before one.
_roster: list[Connection] | None = None


def connection(player: Player | int) -> Connection | None:
    """connection returns the connection of one player, given the player or
    their slot: their name, Steam ID, whether they are a bot and whether they
    finished joining. It returns None when nobody holds the slot."""
    slot = player if isinstance(player, int) else player.slot
    for held in _roster if _roster is not None else players():
        if held.player.slot == slot:
            return held
    return None


def players() -> list[Connection]:
    """players lists the occupied player slots in slot order. It answers from
    the roster the host last reported, and asks the host until a report
    arrives."""
    if _roster is not None:
        return list(_roster)
    response = _call("Players", "Empty", {}, "PlayersResponse")
    if response is None:
        return []
    return response["players"]


# _player_watchers hear each player list the host reports.
_player_watchers: list[Callable[[list[Connection]], object]] = []


def _watch_players(watcher: Callable[[list[Connection]], object]) -> None:
    """_watch_players calls watcher with each player list the host reports,
    and at once with the last one when a report already arrived."""
    _player_watchers.append(watcher)
    if _roster is not None:
        watcher(_roster)


# Cast keeps a mode's players: one member for each human who finished
# joining, made by the mode's join and ended by its leave. Members are keyed
# by slot and connection generation, so a reconnect is a leave and a join.
# Cast learns of joins and leaves from the host's player reports and settles
# them on the next frame; it never walks the player list on a frame where
# nothing changed.
#
# A member may carry a want: to sit on a hero and team, and to come back a
# while after its hero falls. The mode gives one want for every member or a
# function that reads it from the member each frame, so a want follows the
# member's own state. A human whose want leaves the hero free still gets one
# when the game leaves them on a team without a hero, as its own spawn on
# joining can, since nothing else would ever seat them. Each frame Cast
# compares the want with what the member's hero shows, asks the game again at
# most once a second while they differ, and stops asking once they match.
# That is a reconciliation loop: a lost or refused ask is only asked again,
# never reported as a failure.
#
# A frame costs one pawn read per member, which the mode reads back with
# Cast.pawn instead of asking the game again.


@dataclasses.dataclass(frozen=True, slots=True, kw_only=True)
class Want:
    """Want is what a member's hero should be; each field it leaves None is
    free."""

    # hero seats the member on a hero: its name as players know it or as the
    # game does, such as "Calico" or "hero_nano", its id, or "any" for the
    # hero they have or else a random one.
    hero: str | int | None = None
    # team is the team, 2 or 3, to seat the member on. Without one a member
    # keeps their hero's team, or else joins the side with fewer members.
    team: int | None = None
    # respawn is the seconds a fallen hero waits before Cast asks for it back.
    respawn: float | None = None


# _CHANGE_SECONDS is how long Cast leaves a member without a hero after they
# had one, or after they joined when their hero is free. The game's own
# Change Hero removes the hero before it spawns the new one, and seating the
# member in that gap would override their pick.
_CHANGE_SECONDS = 3.0

# _NO_WANT leaves a member's hero free.
_NO_WANT = Want()


@dataclasses.dataclass(slots=True)
class _Seat[M]:
    """_Seat is one member with what Cast last saw of their hero."""

    connection: Connection
    member: M
    # joined_at is when the member joined.
    joined_at: float
    # pawn is the member's hero this frame.
    pawn: Pawn | None = None
    alive: bool = False
    # fell_at is when Cast last saw the hero fall.
    fell_at: float = -math.inf
    # hero is the member's hero last frame, or 0 without one.
    hero: int = 0
    # hero_lost_at is when the member last went from a hero to none.
    hero_lost_at: float = -math.inf
    # asked_at is when Cast last asked the game for the want.
    asked_at: float = -math.inf


class Cast[M]:
    """Cast keeps one member of type M per human player.

    join makes the member for a human who finished joining, and leave ends a
    member whose connection left the slot. want is what every member wants,
    or a function that returns what one member wants now; Cast calls it once
    per member each frame, so it should return a want it keeps rather than
    make a new one. bots says what to do with a bot: "skip" leaves it out of
    the cast, "join" makes it a member as a human is, and "kick" asks the
    server to remove it, once per connection."""

    def __init__(
        self,
        join: Callable[[Connection], M],
        *,
        leave: Callable[[M, Connection], object] | None = None,
        want: Want | Callable[[M], Want] = _NO_WANT,
        bots: Literal["skip", "join", "kick"] = "skip",
    ) -> None:
        self._join = join
        self._leave = leave
        self._want = want
        self._bots = bots
        # _seats holds each member by slot, in the order they joined.
        self._seats: dict[int, _Seat[M]] = {}
        # _kicked holds the connection generation each kicked bot's slot had.
        self._kicked: dict[int, int] = {}
        # _reported is the player list the host reported since the last frame.
        self._reported: list[Connection] | None = None
        # _random draws the hero for "any". It is the cast's own, seeded when
        # the mod makes the cast, because the runtime's shared generator
        # starts from the same seed in every instance.
        self._random = random.Random()
        _watch_players(self._report)

    @property
    def size(self) -> int:
        """size is the number of members."""
        return len(self._seats)

    def members(self) -> list[M]:
        """members lists the members in the order they joined."""
        return [seat.member for seat in self._seats.values()]

    def get(self, player: Player) -> M | None:
        """get returns the member in player's slot, if any."""
        seat = self._seats.get(player.slot)
        return None if seat is None else seat.member

    def pawn(self, player: Player) -> Pawn | None:
        """pawn returns the member's hero as Cast read it this frame."""
        seat = self._seats.get(player.slot)
        return None if seat is None else seat.pawn

    def frame(self, seconds: float) -> None:
        """frame settles the joins and leaves reported since the last frame,
        reads each member's hero, and asks the game once a second for any want
        it does not show yet. seconds is the game clock."""
        if self._reported is not None:
            self._settle(self._reported, seconds)
            self._reported = None
        for seat in self._seats.values():
            self._reconcile(seat, seconds)

    def _report(self, players: list[Connection]) -> None:
        self._reported = players

    def _settle(self, players: list[Connection], now: float) -> None:
        """_settle ends the members whose connection left and makes the new
        ones, joined at now."""
        # A member leaves when their slot empties or a new connection takes it.
        present = {c.player.slot: c for c in players}
        for slot, seat in list(self._seats.items()):
            connection = present.get(slot)
            if connection is None or connection.generation != seat.connection.generation:
                del self._seats[slot]
                if self._leave is not None:
                    self._leave(seat.member, seat.connection)

        # A human who finished joining becomes a member, and a bot as the
        # policy says.
        for connection in players:
            slot = connection.player.slot
            if not connection.ready or slot in self._seats:
                continue
            if connection.bot and self._bots != "join":
                if self._bots == "kick":
                    self._kick(connection)
                continue
            self._seats[slot] = _Seat(connection, self._join(connection), now)

    def _kick(self, connection: Connection) -> None:
        """_kick asks the server to remove a bot, once per connection."""
        slot = connection.player.slot
        if self._kicked.get(slot) == connection.generation:
            return
        self._kicked[slot] = connection.generation
        server_command(f'kick "{connection.name}"')

    def _reconcile(self, seat: _Seat[M], now: float) -> None:
        """_reconcile reads a member's hero and asks for the part of the want
        it lacks."""
        # Note when the hero falls.
        pawn = seat.connection.player.pawn()
        alive = pawn is not None and pawn.hero != 0 and pawn.health > 0
        if seat.alive and not alive:
            seat.fell_at = now
        seat.pawn = pawn
        seat.alive = alive

        # Note when a member who had a hero is left without one, so a hero
        # change the game is making finishes before Cast seats them again.
        had = 0 if pawn is None else pawn.hero
        if had == 0 and seat.hero != 0:
            seat.hero_lost_at = now
        seat.hero = had
        changing = had == 0 and now - seat.hero_lost_at < _CHANGE_SECONDS

        # Ask at most once a second, first for the seat, then for the hero
        # back.
        if now - seat.asked_at < 1 or changing:
            return
        want = self._want if isinstance(self._want, Want) else self._want(seat.member)
        hero = want.hero if want.hero is not None else self._stranded(seat, now)
        if hero is not None and not self._seated(seat, want, hero):
            seat.asked_at = now
            self._seat(seat, want, hero)
        elif (
            want.respawn is not None
            and pawn is not None
            and pawn.hero != 0
            and not alive
            and now - seat.fell_at >= want.respawn
        ):
            seat.asked_at = now
            seat.connection.player.respawn()

    def _stranded(self, seat: _Seat[M], now: float) -> Literal["any"] | None:
        """_stranded returns "any" for a human whose hero is free when the
        game has left them on a team without one for _CHANGE_SECONDS since
        they joined, and otherwise leaves the hero free. Such a pawn never
        gets a hero on its own, while a player still choosing one has no pawn
        and a spectator stands on team 1. A bot is left to the game, which
        seats it."""
        pawn = seat.pawn
        heroless = pawn is not None and pawn.hero == 0 and pawn.team in (2, 3)
        if heroless and not seat.connection.bot and now - seat.joined_at >= _CHANGE_SECONDS:
            return "any"
        return None

    def _seated(self, seat: _Seat[M], want: Want, hero: str | int) -> bool:
        """_seated reports whether the member's hero shows the hero and team
        they want."""
        # A member needs a hero on the team they want before the hero counts.
        pawn = seat.pawn
        if pawn is None or pawn.hero == 0:
            return False
        if want.team is not None and pawn.team != want.team:
            return False
        if hero == "any":
            return True

        # A name outside the released heroes, such as one the game added
        # since, is met by whatever hero the game gave for it.
        if isinstance(hero, int):
            return pawn.hero == hero
        known = hero_named(hero)
        return known is None or pawn.hero == known.id

    def _seat(self, seat: _Seat[M], want: Want, hero: str | int) -> None:
        """_seat asks the game to put the member on hero and their team."""
        # Any hero keeps the one the member has, or else takes a random one.
        pawn = seat.pawn
        pick = hero
        if hero == "any":
            pick = pawn.hero if pawn is not None and pawn.hero != 0 else self._random.choice(HEROES).name
        team = want.team if want.team is not None else self._side(seat)
        seat.connection.player.select_hero(pick, team)

    def _side(self, seat: _Seat[M]) -> int:
        """_side is the team a member joins: their hero's, or the one with
        fewer heroes."""
        # A hero keeps its team. The game puts each connecting player on a
        # team before they have a hero, so a member without one is counted
        # afresh.
        pawn = seat.pawn
        if pawn is not None and pawn.hero != 0 and pawn.team in (2, 3):
            return pawn.team
        amber = sapphire = 0
        for other in self._seats.values():
            if other is seat or other.pawn is None or other.pawn.hero == 0:
                continue
            if other.pawn.team == 2:
                amber += 1
            if other.pawn.team == 3:
                sapphire += 1
        return 3 if sapphire < amber else 2



def set_orbit_camera(player: Player, enabled: bool) -> bool:
    """set_orbit_camera gives the player's hero the hideout's orbit camera,
    zoomed with the wheel, or returns the normal camera. The hideout HUD
    replaces the game HUD while it is on. It returns False when the player has
    no hero or a call fails.

    The pawn's networked m_bInHideoutZone moves its client to the hideout
    view, and the wheel zooms only while the pawn holds
    MODIFIER_STATE_HIDEOUT_ZONE, since the server ignores orbit_camera_in and
    orbit_camera_out without it."""
    pawn = player.pawn()
    if pawn is None or pawn.entity == 0:
        return False
    flag = write_field(pawn.entity, "CCitadelPlayerPawn", "m_bInHideoutZone", "bool", enabled)
    zoom = hold_modifier_state(pawn.entity, "MODIFIER_STATE_HIDEOUT_ZONE", enabled)
    return flag and zoom

def serve(service: str) -> Callable[[Service], Service]:
    """serve answers the host's calls to service with the decorated handler,
    replacing its earlier handler."""

    def register(handler: Service) -> Service:
        _services[service] = handler
        return handler

    return register


def command[F: Callable[[Player, str], object]](name: str) -> Callable[[F], F]:
    """command calls the decorated handler when a player types /name in chat
    or their client sends the console command name to the server. The
    handler runs with the next server frame, before the frame handlers, and
    receives the text after the name, trimmed of surrounding spaces.
    Registering a name again replaces its handler.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.command("hello")
        def hello(player: modlock.Player, args: str) -> None: ...
    """

    def register(handler: F) -> F:
        _commands[name] = handler
        return handler

    return register


def on_start[F: Callable[[list[str]], object]](handler: F) -> F:
    """on_start calls handler once when the server starts the mod, with the
    arguments that follow -- on the modlock-host command line.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_start
        def start(args: list[str]) -> None: ...
    """
    _starts.append(handler)
    return handler


def on_frame[F: Callable[[FrameEvent], object]](handler: F) -> F:
    """on_frame calls handler once per server frame.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_frame
        def frame(event: modlock.FrameEvent) -> None: ...
    """
    _frames.append(handler)
    return handler


class Timer:
    """Timer is one scheduled callback. Time is the game's, so a paused game
    holds its timers. A tick is 1/64 second."""

    def __init__(self) -> None:
        # finished reports whether the timer ran its last time or was
        # cancelled.
        self.finished = False

    def cancel(self) -> None:
        """cancel stops the timer; it does nothing once the timer is finished."""
        self.finished = True


class _Entry(Timer):
    """_Entry is a Timer the clock keeps until it finishes."""

    def __init__(self, delay: float, run: Callable[[], float | None]) -> None:
        super().__init__()
        self.delay = delay
        # run returns the seconds before the entry's next run, or None after
        # its last.
        self.run = run
        # at is the game time the entry next runs. It is unset until started,
        # which waits for the clock when the entry came before the first frame.
        self.started = _now is not None
        self.at = 0.0 if _now is None else _now + delay


# _now is the game time of the latest frame, None before the first.
_now: float | None = None

# _entries are the timers that have not finished, in creation order.
_entries: list[_Entry] = []


def _schedule(delay: float, run: Callable[[], float | None]) -> Timer:
    entry = _Entry(delay, run)
    _entries.append(entry)
    return entry


def after(seconds: float, fn: Callable[[], object]) -> Timer:
    """after runs fn once, seconds from now."""

    def run() -> None:
        fn()

    return _schedule(seconds, run)


def every(seconds: float, fn: Callable[[], object]) -> Timer:
    """every runs fn each seconds, keeping its cadence through a late frame."""

    def run() -> float:
        fn()
        return seconds

    return _schedule(seconds, run)


def sequence(fn: Callable[[int], float | None]) -> Timer:
    """sequence calls fn on the next frame with the number of times it has run,
    starting at 1. fn returns the seconds to wait before it runs again, or None
    to end the sequence."""
    runs = 0

    def run() -> float | None:
        nonlocal runs
        runs += 1
        return fn(runs)

    return _schedule(0, run)


def _advance_timers(seconds: float) -> None:
    """_advance_timers moves the clock to a frame and runs the timers that came
    due, at most once each and in the order they came due. A callback that
    raises ends only its own timer. A clock that runs backward, as a new map's
    does, keeps each timer's remaining delay."""
    global _now, _entries

    # Carry the timers across a clock that went back.
    if _now is not None and seconds < _now:
        shift = seconds - _now
        for entry in _entries:
            if entry.started:
                entry.at += shift
    _now = seconds

    # Start the timers made before the clock was known, then take the due ones.
    # Timers a callback makes wait for the next frame.
    for entry in _entries:
        if not entry.started:
            entry.started = True
            entry.at = seconds + entry.delay
    due = [entry for entry in _entries if not entry.finished and entry.at <= seconds]
    due.sort(key=lambda entry: entry.at)

    for entry in due:
        if entry.finished:
            continue
        try:
            wait = entry.run()
        except Exception as error:
            entry.finished = True
            log(f"timer failed: {error!r}")
            continue
        if wait is None:
            entry.finished = True
        else:
            following = entry.at + wait
            entry.at = following if following > seconds else seconds + wait

    _entries = [entry for entry in _entries if not entry.finished]


def on_world[F: Callable[[str], object]](handler: F) -> F:
    """on_world calls handler with the map's name each time a world loads,
    and at start when one already has. Objects and bots from an earlier
    world are gone by then.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_world
        def world(map: str) -> None: ...
    """
    _worlds.append(handler)
    return handler


def on_input[F: Callable[[Player, Buttons, Buttons], object]](handler: F) -> F:
    """on_input calls handler with the watched buttons a player pressed and
    released before the next frame. A button is held from its press until
    its release.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_input
        def input(player: modlock.Player, pressed: modlock.Buttons, released: modlock.Buttons) -> None: ...
    """
    _inputs.append(handler)
    return handler


def on_restored[F: Callable[[Player, str | None], object]](handler: F) -> F:
    """on_restored calls handler when a player's Player.restore_hero ends:
    the error is None once the target held for a second, or says why it did
    not.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_restored
        def restored(player: modlock.Player, error: str | None) -> None: ...
    """
    _restoreds.append(handler)
    return handler


def on_npcs_restored[F: Callable[[str | None], object]](handler: F) -> F:
    """on_npcs_restored calls handler when restore_npcs ends: the error is
    None once the map holds every target, or says why it does not.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_npcs_restored
        def restored(error: str | None) -> None: ...
    """
    _npcs_restoreds.append(handler)
    return handler


def on_damage[F: Callable[[DamageEvent], DamageResult | None]](handler: F) -> F:
    """on_damage calls handler before each hit lands, so it can block the
    hit or change its damage. Later handlers see the earlier ones'
    amount.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_damage
        def damage(hit: modlock.DamageEvent) -> modlock.DamageResult | None: ...
    """
    _damages.append(handler)
    return handler


def on_chat[F: Callable[[ChatEvent], object]](handler: F) -> F:
    """on_chat calls handler with each chat line a player writes, commands
    included, on the next server frame.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_chat
        def chat(line: modlock.ChatEvent) -> None: ...
    """
    _chats.append(handler)
    return handler


def on_player_join[F: Callable[[PlayerJoinedEvent], object]](handler: F) -> F:
    """on_player_join calls handler once for each player the mod serves when
    they are ready: a human who finished joining, a bot once added, and at
    start each player already in the game.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_player_join
        def join(joined: modlock.PlayerJoinedEvent) -> None: ...
    """
    _joins.append(handler)
    return handler


def on_player_leave[F: Callable[[PlayerLeftEvent], object]](handler: F) -> F:
    """on_player_leave calls handler once for each joined player who leaves
    the mod, with the reason the server dropped them when it gave one. A
    player who disconnects still has their slot and hero during the call. A
    player the mod stops serving leaves too, with disconnected false.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_player_leave
        def leave(left: modlock.PlayerLeftEvent) -> None: ...
    """
    _leaves.append(handler)
    return handler


def on_spawn[F: Callable[[Player, Pawn], object]](handler: F) -> F:
    """on_spawn calls handler each time a player's hero enters play: their
    first hero after joining, each respawn, and each new hero after a change.
    The player has a hero to move, equip and read from then on, which
    on_player_join does not promise. The library reads each player's pawn
    once a frame while a handler is registered.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_spawn
        def spawn(player: modlock.Player, pawn: modlock.Pawn) -> None: ...
    """
    _spawns.append(handler)
    return handler


def _watch_spawns() -> None:
    """_watch_spawns tells the spawn handlers of each hero that entered play
    since the last frame."""
    # A hero is in play while it lives; a placeholder pawn has hero 0.
    present: dict[int, int] = {}
    for connection in players():
        player = connection.player
        pawn = player.pawn()
        if pawn is None or pawn.hero == 0 or pawn.health <= 0:
            continue
        present[player.slot] = pawn.entity

        # A respawn follows a death, and a new hero has a new entity.
        if _spawned.get(player.slot) != pawn.entity:
            for handler in _spawns:
                handler(player, pawn)

    # Forget the fallen and the gone, so their next hero is a spawn.
    _spawned.clear()
    _spawned.update(present)


def on_damaged[F: Callable[[DamagedEvent], object]](handler: F) -> F:
    """on_damaged calls handler on the frame after each hit lands.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_damaged
        def damaged(hit: modlock.DamagedEvent) -> None: ...
    """
    _damageds.append(handler)
    return handler


def on_launch[F: Callable[[LaunchEvent], object]](handler: F) -> F:
    """on_launch calls handler with each watched projectile's first frame,
    before the next frame. watch_projectiles names the projectiles.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_launch
        def launch(projectile: modlock.LaunchEvent) -> None: ...
    """
    _launches.append(handler)
    return handler


def on_impact[F: Callable[[ImpactEvent], object]](handler: F) -> F:
    """on_impact calls handler when a watched projectile strikes something,
    inside the game's impact: its calls apply before the game continues.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_impact
        def impact(hit: modlock.ImpactEvent) -> None: ...
    """
    _impacts.append(handler)
    return handler


def on_landed[F: Callable[[LandedEvent], object]](handler: F) -> F:
    """on_landed calls handler when a hero lands under the manifest's
    QuakeWorld movement, before the next frame.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_landed
        def landed(landing: modlock.LandedEvent) -> None: ...
    """
    _landeds.append(handler)
    return handler


def on_setting_changed[F: Callable[[Player, str, str], object]](handler: F) -> F:
    """on_setting_changed calls handler when a player's setting changes
    outside the mod, such as on the player's profile. The mod's own
    Player.set_setting calls do not reach it.

    Annotate the handler's parameters, since a checker and an editor's
    completion read their types from there:

        @modlock.on_setting_changed
        def changed(player: modlock.Player, key: str, value: str) -> None: ...
    """
    _setting_changes.append(handler)
    return handler


def _start(event: StartEvent) -> StartResult:
    for handler in _starts:
        handler(event.args)
    # Timers run from frames, so the library always takes them.
    return StartResult(
        frames=True,
        damage=bool(_damages),
        damaged=bool(_damageds),
        chat=bool(_chats),
        joins=bool(_joins or _leaves),
    )


# UiValue is an input's new value as the host checked it.
type UiValue = str | float | bool | int | Wheel | None


@dataclasses.dataclass(frozen=True, slots=True)
class _UiHandlers:
    """_UiHandlers are modlock.ui's handlers of the events its interfaces
    raise, which it registers when a mod imports it."""

    # press runs the handler of the button a player pressed.
    press: Callable[[Player, str], object]
    # change runs the handler of the input a player changed.
    change: Callable[[Player, str, UiValue], object]
    # tick advances the interface clock to each frame.
    tick: Callable[[float], object]


# _ui holds modlock.ui's handlers, or None while the mod shows no interface.
_ui: _UiHandlers | None = None


def _serve_ui(handlers: _UiHandlers) -> None:
    """_serve_ui passes presses, input changes and the frame clock to
    modlock.ui, which imports this module and so registers itself."""
    global _ui
    _ui = handlers


def _frame(event: FrameEvent) -> None:
    if _ui is not None:
        _ui.tick(event.time_seconds)
    _advance_timers(event.time_seconds)
    if _spawns:
        _watch_spawns()
    for handler in _frames:
        handler(event)


def _command(event: CommandEvent) -> CommandResult:
    # Split the command line into its name and arguments.
    name, _, args = event.line.strip().partition(" ")
    handler = _commands.get(name)
    if handler is None:
        return CommandResult(claimed=False)

    # Claim the command and run its handler with the next frame. The server
    # reads a client's commands under a CPU budget and drops the client when
    # one handler spends it; slow work in a frame only delays that frame.
    player, text = event.player, args.strip()
    after(0, lambda: handler(player, text))
    return CommandResult(claimed=True)


def _chat(event: ChatEvent) -> None:
    # The line arrives under the same CPU budget as a command, so its
    # handlers run with the next frame.
    def run() -> None:
        for handler in _chats:
            handler(event)

    after(0, run)


def _world(event: WorldEvent) -> None:
    for handler in _worlds:
        handler(event.map)


def _ui_press(event: UiPressEvent) -> None:
    # A press arrives under the same CPU budget as a command, so its handler
    # also runs with the next frame.
    ui = _ui
    if ui is not None:
        player, node = event.player, event.node
        after(0, lambda: ui.press(player, node))


def _ui_input(event: UiInputEvent) -> None:
    # A change runs with the next frame, as a press does.
    ui = _ui
    if ui is not None:
        player, node, value = event.player, event.node, event.value
        after(0, lambda: ui.change(player, node, value))


def _serve(event: ServiceCall) -> ServiceReply:
    handler = _services.get(event.service)
    if handler is None:
        raise LookupError("the mod serves no service " + event.service)
    return ServiceReply(payload=handler(event.method, event.payload))


def _damage(event: DamageEvent) -> DamageResult | None:
    amount = event.amount
    for handler in _damages:
        change = handler(dataclasses.replace(event, amount=amount))
        if change is not None and change.block:
            return DamageResult(block=True)
        if change is not None and change.amount is not None:
            amount = change.amount
    return None if amount == event.amount else DamageResult(amount=amount)


def _damaged(event: DamagedEvent) -> None:
    for handler in _damageds:
        handler(event)


def _input(event: InputEvent) -> None:
    for handler in _inputs:
        handler(event.player, Buttons(event.pressed), Buttons(event.released))


def _restored(event: RestoredEvent) -> None:
    for handler in _restoreds:
        handler(event.player, event.error or None)


def _npcs_restored(event: NpcsRestoredEvent) -> None:
    for handler in _npcs_restoreds:
        handler(event.error or None)


def _launch(event: LaunchEvent) -> None:
    for handler in _launches:
        handler(event)


def _impact(event: ImpactEvent) -> None:
    for handler in _impacts:
        handler(event)


def _landed(event: LandedEvent) -> None:
    for handler in _landeds:
        handler(event)


def _setting_changed(event: SettingChangedEvent) -> None:
    for handler in _setting_changes:
        handler(event.player, event.key, event.value)


def _players_changed(event: PlayersChangedEvent) -> None:
    global _roster
    _roster = event.players
    for watcher in _player_watchers:
        watcher(_roster)


# A join and a leave run at once, so the leaving player's hero still reads.
def _player_joined(event: PlayerJoinedEvent) -> None:
    for handler in _joins:
        handler(event)


def _player_left(event: PlayerLeftEvent) -> None:
    for handler in _leaves:
        handler(event)


# _HANDLERS delivers each event to the handlers the mod registered.
_HANDLERS: dict[str, Callable[[Any], Any]] = {
    "start": _start,
    "frame": _frame,
    "command": _command,
    "chat": _chat,
    "world": _world,
    "ui_press": _ui_press,
    "ui_input": _ui_input,
    "serve": _serve,
    "damage": _damage,
    "damaged": _damaged,
    "input": _input,
    "restored": _restored,
    "npcs_restored": _npcs_restored,
    "launch": _launch,
    "impact": _impact,
    "landed": _landed,
    "setting_changed": _setting_changed,
    "players_changed": _players_changed,
    "player_joined": _player_joined,
    "player_left": _player_left,
}

_modlock.handle(lambda data: _serve_mod(_HANDLERS, data))
